{"file_path":"./src/parser.js","content":"/**
 * The parser for the configuration document format described in the task.
 * `parseDocument` reads the whole document and returns the root table, or
 * throws a `ParseError` naming the first line that fails to parse.
 */

const INT_RE = /^[+-]?\d+(_\d+)*$/
const FLOAT_RE = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/
const NAME_CHAR_RE = /[A-Za-z0-9_-]/

export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

/** A table node: an ordered map of keys to values, plus whether a `[name]`
 * header has already made this exact table current (which blocks a second
 * such header from naming it again). */
class TableNode {
  constructor() {
    this.entries = new Map()
    this.headerDefined = false
  }
}

const VTable = (node) => ({ t: 'table', v: node })
const VArray = (items, isAOT) => ({ t: 'array', v: items, isAOT: !!isAOT })
const VString = (s) => ({ t: 'string', v: s })
const VInt = (bi) => ({ t: 'integer', v: bi })
const VFloat = (n) => ({ t: 'float', v: n })
const VBool = (b) => ({ t: 'boolean', v: b })

function isBarewordDelim(ch) {
  return ch === ' ' || ch === '\t' || ch === ',' || ch === ']' || ch === '}'
}

function skipWS(ctx) {
  while (ctx.i < ctx.n && (ctx.line[ctx.i] === ' ' || ctx.line[ctx.i] === '\t')) ctx.i++
}

function readBasicStringRaw(ctx) {
  ctx.i++ // consume opening quote
  let result = ''
  while (true) {
    if (ctx.i >= ctx.n) throw new ParseError(ctx.lineNo, 'unterminated string')
    const c = ctx.line[ctx.i]
    if (c === '"') { ctx.i++; return result }
    if (c === '\\') {
      ctx.i++
      if (ctx.i >= ctx.n) throw new ParseError(ctx.lineNo, 'unterminated string')
      const e = ctx.line[ctx.i]
      if (e === '"') { result += '"'; ctx.i++ }
      else if (e === '\\') { result += '\\'; ctx.i++ }
      else if (e === 'n') { result += '\n'; ctx.i++ }
      else if (e === 't') { result += '\t'; ctx.i++ }
      else if (e === 'r') { result += '\r'; ctx.i++ }
      else if (e === '0') { result += '\0'; ctx.i++ }
      else if (e === 'u') {
        const hex = ctx.line.slice(ctx.i + 1, ctx.i + 5)
        if (hex.length === 4 && /^[0-9a-fA-F]{4}$/.test(hex)) {
          result += String.fromCharCode(parseInt(hex, 16))
          ctx.i += 5
        } else {
          throw new ParseError(ctx.lineNo, 'invalid escape \\u')
        }
      } else {
        throw new ParseError(ctx.lineNo, `invalid escape \\${e}`)
      }
    } else {
      result += c
      ctx.i++
    }
  }
}

function readLiteralStringRaw(ctx) {
  ctx.i++ // consume opening quote
  const start = ctx.i
  while (ctx.i < ctx.n && ctx.line[ctx.i] !== "'") ctx.i++
  if (ctx.i >= ctx.n) throw new ParseError(ctx.lineNo, 'unterminated string')
  const result = ctx.line.slice(start, ctx.i)
  ctx.i++
  return result
}

function readName(ctx) {
  skipWS(ctx)
  if (ctx.i >= ctx.n) throw new ParseError(ctx.lineNo, 'expected a name')
  const c = ctx.line[ctx.i]
  if (c === '"') return readBasicStringRaw(ctx)
  if (c === "'") return readLiteralStringRaw(ctx)
  const start = ctx.i
  while (ctx.i < ctx.n && NAME_CHAR_RE.test(ctx.line[ctx.i])) ctx.i++
  if (ctx.i === start) throw new ParseError(ctx.lineNo, 'expected a name')
  return ctx.line.slice(start, ctx.i)
}

function readDottedName(ctx) {
  const segs = []
  while (true) {
    segs.push(readName(ctx))
    skipWS(ctx)
    if (ctx.line[ctx.i] === '.') { ctx.i++; continue }
    break
  }
  return segs
}

function parseBareValue(text, lineNo) {
  if (text === 'true') return VBool(true)
  if (text === 'false') return VBool(false)
  if (INT_RE.test(text)) {
    let t = text.replace(/_/g, '')
    if (t[0] === '+') t = t.slice(1)
    return VInt(BigInt(t))
  }
  if (FLOAT_RE.test(text) && (text.includes('.') || /[eE]/.test(text))) {
    return VFloat(Number(text.replace(/_/g, '')))
  }
  throw new ParseError(lineNo, `invalid value ${text}`)
}

function readValue(ctx, pathPrefix) {
  skipWS(ctx)
  if (ctx.i >= ctx.n) throw new ParseError(ctx.lineNo, 'expected a value')
  const c = ctx.line[ctx.i]
  if (c === '#' || c === ';' || c === ',' || c === ']' || c === '}') {
    throw new ParseError(ctx.lineNo, 'expected a value')
  }
  if (c === '"') return VString(readBasicStringRaw(ctx))
  if (c === "'") return VString(readLiteralStringRaw(ctx))
  if (c === '[') return readArray(ctx, pathPrefix)
  if (c === '{') return readInlineTable(ctx, pathPrefix)
  const start = ctx.i
  while (ctx.i < ctx.n && !isBarewordDelim(ctx.line[ctx.i])) ctx.i++
  const text = ctx.line.slice(start, ctx.i)
  return parseBareValue(text, ctx.lineNo)
}

function readArray(ctx, pathPrefix) {
  ctx.i++ // consume '['
  const items = []
  while (true) {
    skipWS(ctx)
    if (ctx.i >= ctx.n) throw new ParseError(ctx.lineNo, 'unterminated array')
    let c = ctx.line[ctx.i]
    if (c === '#' || c === ';') throw new ParseError(ctx.lineNo, 'unterminated array')
    if (c === ']') { ctx.i++; break }
    items.push(readValue(ctx, pathPrefix))
    skipWS(ctx)
    if (ctx.i >= ctx.n) throw new ParseError(ctx.lineNo, 'unterminated array')
    c = ctx.line[ctx.i]
    if (c === '#' || c === ';') throw new ParseError(ctx.lineNo, 'unterminated array')
    if (c === ',') { ctx.i++; continue }
    if (c === ']') { ctx.i++; break }
    throw new ParseError(ctx.lineNo, 'trailing text after a value')
  }
  return VArray(items, false)
}

function readInlineTable(ctx, pathPrefix) {
  ctx.i++ // consume '{'
  const node = new TableNode()
  let first = true
  while (true) {
    skipWS(ctx)
    if (ctx.i >= ctx.n) throw new ParseError(ctx.lineNo, 'unterminated inline table')
    let c = ctx.line[ctx.i]
    if (c === '#' || c === ';') throw new ParseError(ctx.lineNo, 'unterminated inline table')
    if (c === '}') {
      if (first) { ctx.i++; break }
      throw new ParseError(ctx.lineNo, 'expected a name')
    }
    const segs = readDottedName(ctx)
    skipWS(ctx)
    if (ctx.line[ctx.i] !== '=') throw new ParseError(ctx.lineNo, 'expected = in an inline table')
    ctx.i++
    const fullSegs = pathPrefix.concat(segs)
    const val = readValue(ctx, fullSegs)
    const parent = walkIntermediate(node, segs.slice(0, -1), pathPrefix, ctx.lineNo)
    const last = segs[segs.length - 1]
    if (parent.entries.has(last)) throw new ParseError(ctx.lineNo, `key ${fullSegs.join('.')} is defined twice`)
    parent.entries.set(last, val)
    skipWS(ctx)
    if (ctx.i >= ctx.n) throw new ParseError(ctx.lineNo, 'unterminated inline table')
    c = ctx.line[ctx.i]
    if (c === '#' || c === ';') throw new ParseError(ctx.lineNo, 'unterminated inline table')
    if (c === ',') { ctx.i++; first = false; continue }
    if (c === '}') { ctx.i++; break }
    throw new ParseError(ctx.lineNo, 'trailing text after a value')
  }
  return VTable(node)
}

/** Walks `segs` from `node`, creating implicit tables as needed and
 * descending through the last element of an array of tables, and returns
 * the table reached. `basePath` is the root path of `node`, used to build
 * full paths in error messages. */
function walkIntermediate(node, segs, basePath, lineNo) {
  let cur = node
  for (let k = 0; k < segs.length; k++) {
    const seg = segs[k]
    const existing = cur.entries.get(seg)
    if (existing === undefined) {
      const nt = new TableNode()
      cur.entries.set(seg, VTable(nt))
      cur = nt
    } else if (existing.t === 'table') {
      cur = existing.v
    } else if (existing.t === 'array' && existing.isAOT) {
      cur = existing.v[existing.v.length - 1].v
    } else {
      const fullPath = basePath.concat(segs.slice(0, k + 1)).join('.')
      throw new ParseError(lineNo, `${fullPath} is not a table`)
    }
  }
  return cur
}

function processAssignment(raw, lineNo, current, currentPath) {
  const ctx = { line: raw, i: 0, n: raw.length, lineNo }
  const segs = readDottedName(ctx)
  skipWS(ctx)
  if (ctx.line[ctx.i] !== '=') throw new ParseError(lineNo, 'expected key = value')
  ctx.i++
  const fullSegs = currentPath.concat(segs)
  const value = readValue(ctx, fullSegs)
  skipWS(ctx)
  if (ctx.i < ctx.n) {
    const c = ctx.line[ctx.i]
    if (c !== '#' && c !== ';') throw new ParseError(lineNo, 'trailing text after a value')
  }
  const parent = walkIntermediate(current, segs.slice(0, -1), currentPath, lineNo)
  const last = segs[segs.length - 1]
  if (parent.entries.has(last)) throw new ParseError(lineNo, `key ${fullSegs.join('.')} is defined twice`)
  parent.entries.set(last, value)
}

function processHeader(raw, lineNo, rootNode) {
  const ctx = { line: raw, i: 0, n: raw.length, lineNo }
  skipWS(ctx)
  ctx.i++ // consume the first '['
  let isArray = false
  if (ctx.line[ctx.i] === '[') { isArray = true; ctx.i++ }
  const segments = readDottedName(ctx)
  skipWS(ctx)
  if (isArray) {
    if (ctx.line[ctx.i] === ']' && ctx.line[ctx.i + 1] === ']') ctx.i += 2
    else throw new ParseError(lineNo, 'unterminated table header')
  } else {
    if (ctx.line[ctx.i] === ']') ctx.i += 1
    else throw new ParseError(lineNo, 'unterminated table header')
  }
  skipWS(ctx)
  if (ctx.i < ctx.n) {
    const c = ctx.line[ctx.i]
    if (c !== '#' && c !== ';') throw new ParseError(lineNo, 'trailing text after a table header')
  }
  const fullPath = segments.join('.')
  const last = segments.length - 1
  const parent = walkIntermediate(rootNode, segments.slice(0, last), [], lineNo)
  const key = segments[last]
  const existing = parent.entries.get(key)
  if (isArray) {
    let arr
    if (existing === undefined) {
      arr = VArray([], true)
      parent.entries.set(key, arr)
    } else if (existing.t === 'array' && existing.isAOT) {
      arr = existing
    } else {
      throw new ParseError(lineNo, `${fullPath} is not an array of tables`)
    }
    const nt = new TableNode()
    arr.v.push(VTable(nt))
    return { node: nt, path: segments }
  }
  if (existing === undefined) {
    const nt = new TableNode()
    nt.headerDefined = true
    parent.entries.set(key, VTable(nt))
    return { node: nt, path: segments }
  }
  if (existing.t === 'table') {
    if (existing.v.headerDefined) throw new ParseError(lineNo, `table ${fullPath} is defined twice`)
    existing.v.headerDefined = true
    return { node: existing.v, path: segments }
  }
  throw new ParseError(lineNo, `${fullPath} is not a table`)
}

function firstNonWsIndex(line) {
  for (let i = 0; i < line.length; i++) {
    const c = line[i]
    if (c !== ' ' && c !== '\t') return i
  }
  return -1
}

export function parseDocument(text) {
  const rootNode = new TableNode()
  let current = rootNode
  let currentPath = []

  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  for (let idx = 0; idx < lines.length; idx++) {
    const lineNo = idx + 1
    const raw = lines[idx]
    const start = firstNonWsIndex(raw)
    if (start === -1) continue
    const c0 = raw[start]
    if (c0 === '#' || c0 === ';') continue
    if (c0 === '[') {
      const result = processHeader(raw, lineNo, rootNode)
      current = result.node
      currentPath = result.path
    } else {
      processAssignment(raw, lineNo, current, currentPath)
    }
  }

  return rootNode
}
