const VArray = (items, isAOT) => ({ t: 'array', v: items, isAOT: !!isAOT })
const VString = (s) => ({ t: 'string', v: s })
const VInt = (bi) => ({ t: 'integer', v: bi })
const VFloat = (n) => ({ t: 'float', v: n })
