  const fullPath = segments.join('.')
  const last = segments.length - 1
  const parent = walkIntermediate(rootNode, segments.slice(0, last), [], lineNo)
  const key = segments[last]
  const existing = parent.entries.get(key)
  if (isArray) {
    let arr
    if (existing === undefined) {
      arr = VArray([], true)
      parent.entries.set(key, arr)
    } else if (existing.t === 'array' && existing.isAOT) {
      arr = existing
    } else {
      throw new ParseError(lineNo, `${fullPath} is not an array of tables`)
    }
